import{_ as t,o as r,c as o,a2 as i}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"History","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/history.md","filePath":"user-guide/settings/history.md","lastUpdated":1787586465000}'),s={name:"user-guide/settings/history.md"};function a(n,e,l,d,c,g){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h1><p>The History settings page manages usage traces and adaptive recall rankings. Top tabs include: <strong>Search History</strong> and <strong>Keyword History</strong>.</p><h2 id="_1-search-history" tabindex="-1">1. Search History <a class="header-anchor" href="#_1-search-history" aria-label="Permalink to &quot;1. Search History&quot;">​</a></h2><p>Search History tracks items and applications you have actually launched, binding the search query to the target physical path:</p><ul><li><strong>Adaptive Prioritized Recall</strong>: When you type characters related to past queries, Lertaro prioritizes previously opened items at the top of results. For instance, if you launched <code>BCompare.exe</code> by searching <code>bcomp</code>, future searches for <code>bc</code> will still boost it to the top.</li><li><strong>Inline Window Grouping</strong>: Inside file dialogs, matching historical items within the active folder appear under &quot;Current Folder&quot;, while others appear under &quot;Global Search&quot;.</li><li><strong>Dead Link Filtering</strong>: If an indexed path is moved or deleted, Lertaro automatically skips missing entries, guaranteeing unique rows.</li><li><strong>Management Controls</strong>: <ul><li><strong>Enable History</strong>: Master toggle; existing entries are retained when disabled, but new launches are not recorded.</li><li><strong>Search Filter</strong>: Narrows the visible history list by keyword.</li><li><strong>Single Delete &amp; Clear All</strong>: Remove individual rows or click <strong>Clear All History</strong> to wipe everything.</li></ul></li></ul><h2 id="_2-keyword-history" tabindex="-1">2. Keyword History <a class="header-anchor" href="#_2-keyword-history" aria-label="Permalink to &quot;2. Keyword History&quot;">​</a></h2><p>Keyword History specifically remembers the <strong>raw query strings</strong> typed into the Quick Window:</p><ul><li><strong>Hotkey Navigation</strong>: Inside the Quick Window, press <strong><code>Alt+Up</code></strong> / <strong><code>Alt+Down</code></strong> to cycle backward and forward through recent queries. Press <strong><code>Ctrl+Delete</code></strong> to delete the currently active term.</li><li><strong>Independent Maintenance</strong>: Includes its own <strong>Enable History</strong> toggle, search filter, single-entry deletion, and <strong>Clear All History</strong> button.</li></ul>',8)])])}const y=t(s,[["render",a]]);export{u as __pageData,y as default};
